IF DB_ID(N'JaipurBusinessHub') IS NULL CREATE DATABASE JaipurBusinessHub;
GO
USE JaipurBusinessHub;
GO
IF OBJECT_ID(N'dbo.Users',N'U') IS NOT NULL RETURN;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.Roles(Id int IDENTITY PRIMARY KEY,Name nvarchar(40) NOT NULL UNIQUE);
CREATE TABLE dbo.Permissions(Id int IDENTITY PRIMARY KEY,Code nvarchar(100) NOT NULL UNIQUE,Description nvarchar(240) NOT NULL);
CREATE TABLE dbo.RolePermissions(RoleId int NOT NULL REFERENCES dbo.Roles(Id),PermissionId int NOT NULL REFERENCES dbo.Permissions(Id),CONSTRAINT PK_RolePermissions PRIMARY KEY(RoleId,PermissionId));
CREATE TABLE dbo.Users(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),Email nvarchar(320) NOT NULL UNIQUE,Phone nvarchar(24) NOT NULL UNIQUE,FullName nvarchar(160) NOT NULL,PasswordHash nvarchar(500) NOT NULL,Role nvarchar(40) NOT NULL DEFAULT 'Buyer',IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_Users_Role CHECK(Role IN('Buyer','Supplier','ServiceProvider','Manufacturer','Admin')));
CREATE TABLE dbo.UserRoles(UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),RoleId int NOT NULL REFERENCES dbo.Roles(Id),CONSTRAINT PK_UserRoles PRIMARY KEY(UserId,RoleId));
CREATE TABLE dbo.Cities(Id int IDENTITY PRIMARY KEY,Name nvarchar(100) NOT NULL,StateCode char(2) NOT NULL,IsActive bit NOT NULL DEFAULT 1,CONSTRAINT UQ_Cities UNIQUE(Name,StateCode));
CREATE TABLE dbo.Areas(Id int IDENTITY PRIMARY KEY,CityId int NOT NULL REFERENCES dbo.Cities(Id),Name nvarchar(120) NOT NULL,PostalCode char(6) NULL,CONSTRAINT UQ_Areas UNIQUE(CityId,Name));
CREATE TABLE dbo.Businesses(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),OwnerId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),Name nvarchar(200) NOT NULL,Slug nvarchar(220) NOT NULL UNIQUE,Description nvarchar(max) NOT NULL,BusinessType nvarchar(60) NOT NULL,Gstin nvarchar(15) NOT NULL DEFAULT '',Phone nvarchar(24) NOT NULL,Email nvarchar(320) NOT NULL,City nvarchar(100) NOT NULL DEFAULT 'Jaipur',Area nvarchar(120) NOT NULL DEFAULT '',Address nvarchar(500) NOT NULL DEFAULT '',IsVerified bit NOT NULL DEFAULT 0,IsPublished bit NOT NULL DEFAULT 0,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_Businesses_Owner ON dbo.Businesses(OwnerId); CREATE INDEX IX_Businesses_Area ON dbo.Businesses(City,Area,IsPublished);
CREATE TABLE dbo.BusinessCategories(BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id) ON DELETE CASCADE,Category nvarchar(120) NOT NULL,CONSTRAINT PK_BusinessCategories PRIMARY KEY(BusinessId,Category));
CREATE TABLE dbo.Listings(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id) ON DELETE CASCADE,Kind nvarchar(20) NOT NULL,Name nvarchar(200) NOT NULL,Category nvarchar(120) NOT NULL,Description nvarchar(max) NOT NULL,PriceFrom decimal(19,4) NULL,PriceTo decimal(19,4) NULL,Unit nvarchar(40) NOT NULL DEFAULT '',MinimumOrderQuantity int NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_Listings_Kind CHECK(Kind IN('Product','Service')),CONSTRAINT CK_Listings_Price CHECK(PriceFrom IS NULL OR PriceTo IS NULL OR PriceFrom<=PriceTo));
CREATE INDEX IX_Listings_Search ON dbo.Listings(Kind,Category,IsActive); CREATE INDEX IX_Listings_Business ON dbo.Listings(BusinessId,IsActive);
CREATE TABLE dbo.Products(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),Name nvarchar(200) NOT NULL,Category nvarchar(120) NOT NULL,Description nvarchar(max) NOT NULL,PriceFrom decimal(19,4) NULL,PriceTo decimal(19,4) NULL,Unit nvarchar(40) NOT NULL,MinimumOrderQuantity int NULL,ImageUrl nvarchar(1000) NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Services(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),Name nvarchar(200) NOT NULL,Category nvarchar(120) NOT NULL,Description nvarchar(max) NOT NULL,PriceFrom decimal(19,4) NULL,DeliveryMode nvarchar(40) NOT NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Leads(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BuyerId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),Title nvarchar(200) NOT NULL,Category nvarchar(120) NOT NULL,Quantity decimal(19,4) NOT NULL,Unit nvarchar(40) NOT NULL,City nvarchar(100) NOT NULL DEFAULT 'Jaipur',Area nvarchar(120) NOT NULL DEFAULT '',Description nvarchar(max) NOT NULL,Status nvarchar(24) NOT NULL DEFAULT 'Open',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_Leads_Quantity CHECK(Quantity>0));
CREATE INDEX IX_Leads_OpenLocation ON dbo.Leads(Status,City,Area,CreatedAt DESC); CREATE INDEX IX_Leads_Buyer ON dbo.Leads(BuyerId,CreatedAt DESC);
CREATE TABLE dbo.RFQs(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),LeadId uniqueidentifier NOT NULL UNIQUE REFERENCES dbo.Leads(Id),DeliveryDate date NULL,Currency char(3) NOT NULL DEFAULT 'INR',Status nvarchar(24) NOT NULL DEFAULT 'Open',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Quotations(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),LeadId uniqueidentifier NOT NULL REFERENCES dbo.Leads(Id),SupplierBusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),Amount decimal(19,4) NOT NULL,Currency char(3) NOT NULL DEFAULT 'INR',Terms nvarchar(2000) NOT NULL,ValidDays int NOT NULL DEFAULT 7,Status nvarchar(24) NOT NULL DEFAULT 'Submitted',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_Quotations_LeadSupplier UNIQUE(LeadId,SupplierBusinessId),CONSTRAINT CK_Quotations_Amount CHECK(Amount>0),CONSTRAINT CK_Quotations_Valid CHECK(ValidDays BETWEEN 1 AND 90));
CREATE TABLE dbo.Reviews(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),AuthorId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),Rating tinyint NOT NULL,Body nvarchar(2000) NOT NULL,Status nvarchar(24) NOT NULL DEFAULT 'Pending',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_Reviews_Rating CHECK(Rating BETWEEN 1 AND 5));
CREATE INDEX IX_Reviews_Business ON dbo.Reviews(BusinessId,Status,CreatedAt DESC);
CREATE TABLE dbo.SavedBusinesses(UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_SavedBusinesses PRIMARY KEY(UserId,BusinessId));
CREATE TABLE dbo.Subscriptions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),BusinessId uniqueidentifier NOT NULL REFERENCES dbo.Businesses(Id),PlanCode nvarchar(30) NOT NULL,Status nvarchar(24) NOT NULL,StartsAt datetime2 NOT NULL,EndsAt datetime2 NOT NULL,RazorpaySubscriptionId nvarchar(120) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Payments(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),SubscriptionId uniqueidentifier NOT NULL REFERENCES dbo.Subscriptions(Id),Provider nvarchar(30) NOT NULL,ProviderPaymentId nvarchar(120) NULL,Amount decimal(19,4) NOT NULL,Currency char(3) NOT NULL DEFAULT 'INR',Status nvarchar(24) NOT NULL,IdempotencyKey nvarchar(120) NOT NULL UNIQUE,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.Notifications(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),Channel nvarchar(24) NOT NULL,TemplateKey nvarchar(100) NOT NULL,Payload nvarchar(max) NOT NULL,Status nvarchar(24) NOT NULL DEFAULT 'Pending',ProviderMessageId nvarchar(200) NULL,RetryCount int NOT NULL DEFAULT 0,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_Notifications_Queue ON dbo.Notifications(Status,CreatedAt);
CREATE TABLE dbo.Messages(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),LeadId uniqueidentifier NULL REFERENCES dbo.Leads(Id),SenderId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),RecipientId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),Body nvarchar(4000) NOT NULL,ReadAt datetime2 NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_Messages_Thread ON dbo.Messages(LeadId,CreatedAt);
CREATE TABLE dbo.RefreshSessions(Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWSEQUENTIALID(),UserId uniqueidentifier NOT NULL REFERENCES dbo.Users(Id),TokenHash char(64) NOT NULL UNIQUE,ExpiresAt datetime2 NOT NULL,RevokedAt datetime2 NULL);
CREATE TABLE dbo.AuditLogs(Id bigint IDENTITY PRIMARY KEY,ActorId uniqueidentifier NULL REFERENCES dbo.Users(Id),Action nvarchar(120) NOT NULL,Entity nvarchar(120) NOT NULL,Ip nvarchar(64) NOT NULL DEFAULT '',CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_AuditLogs_CreatedAt ON dbo.AuditLogs(CreatedAt DESC);
INSERT dbo.Roles(Name) VALUES('Buyer'),('Supplier'),('ServiceProvider'),('Manufacturer'),('Admin');
INSERT dbo.Cities(Name,StateCode) VALUES('Jaipur','RJ');
COMMIT TRANSACTION;
